<?php /** @var array $rows @var int $page @var int $pages @var string $st @var array $stats @var $top */ ?>
<div class="kpis"><div class="kpi"><b><?= (int) $stats['total'] ?></b><small>Referrals</small></div><div class="kpi"><b><?= (int) $stats['conv'] ?>%</b><small>Conversion to purchase</small></div><div class="kpi"><b><?= (int) $stats['rewarded'] ?></b><small>Successful</small></div><div class="kpi"><b><?= (int) $stats['pending'] ?></b><small>Pending</small></div><div class="kpi"><b><?= (int) $stats['awaiting'] ?></b><small>Awaiting approval</small></div><div class="kpi"><b><?= (int) $stats['flagged'] ?></b><small>Flagged / fraud</small></div></div>
<div class="tabs"><?php foreach (['' => 'All', 'registered' => 'Signed up', 'qualified' => 'Awaiting approval', 'rewarded' => 'Rewarded', 'rejected' => 'Rejected / flagged'] as $k => $l): ?><a href="<?= e(url('admin/loyalty/referrals' . ($k ? '?status=' . $k : ''))) ?>" class="<?= $st === $k ? 'on' : '' ?>"><?= $l ?></a><?php endforeach; ?></div>
<section class="apanel flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Date</th><th>Referrer</th><th>Referred customer</th><th>Status</th><th>Reward</th><th>Notes</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td class="muted"><?= e(fmt_date($r->created_at, false)) ?></td><td><b><?= e($r->referrer) ?></b><small><?= e($r->referrer_email) ?> · <?= e($r->code) ?></small></td><td><b><?= e($r->referee) ?></b><small><?= e($r->referee_email) ?></small></td>
<td><span class="pill <?= $r->status === 'rewarded' ? 'ok' : '' ?>"><?= e($r->status) ?></span><?= $r->flagged ? ' <span class="pill" style="border-color:#ff6b7d">⚑ fraud</span>' : '' ?></td><td><?= $r->reward_points ? number_format($r->reward_points) . ' pts' : '—' ?><?= $r->reward_cashback ? ' + ' . money($r->reward_cashback) : '' ?></td><td class="muted small"><?= e($r->note) ?></td>
<td class="r"><?php if (in_array($r->status, ['qualified', 'registered'], true)): ?><form method="post" action="<?= e(url('admin/loyalty/referrals/' . $r->id . '/approve')) ?>" style="display:inline"><?= csrf_field() ?><button class="btn sm" <?= $r->status === 'registered' ? 'data-confirm="This friend has not purchased yet. Reward anyway?"' : '' ?>>Approve</button></form>
<form method="post" action="<?= e(url('admin/loyalty/referrals/' . $r->id . '/reject')) ?>" style="display:inline"><?= csrf_field() ?><button class="btn sm ghost danger" data-confirm="Reject this referral?">Reject</button></form><?php endif; ?></td></tr>
<?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7" class="empty">No referrals yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?= partial('admin/_pager', compact('page', 'pages')) ?>
<section class="apanel"><h2>Top referrers &amp; ambassadors</h2><?php foreach ($top as $t): ?><div class="ph" style="margin:0 0 8px"><span><a href="<?= e(url('admin/loyalty/members/' . $t->id)) ?>"><?= e($t->name) ?></a> <?= $t->ambassador ? '<span class="pill ok">★ ambassador</span>' : '' ?></span><b><?= (int) $t->ok ?> rewarded / <?= (int) $t->c ?></b></div><?php endforeach; ?><p class="muted small">Referral rewards, qualifying purchase, limits and campaign dates: Programme settings → Referrals. Make a member an ambassador or set a custom code on their profile.</p></section>
